# Resolve a named native function without evaluating user code.
seurat_cluster_function <- function(a,name,default) {
 value <- if(is.null(a[[name]])) default else a[[name]]
 parts <- strsplit(value,"::",fixed=TRUE)[[1]]
 if(length(parts)==1L) get(parts[1],asNamespace("Seurat"),mode="function") else if(length(parts)==2L) getExportedValue(parts[1],parts[2]) else stop("Supply a Seurat function name or package::function")
}
OSC_MODULE_VERSION <- "1.0.0"
