 x <- Seurat::FindClusters(graph.name="omic_snn", cluster.name="cluster", modularity.fxn=os_seurat_option(a,"cluster-modularity-fxn",1), initial.membership=os_seurat_option(a,"cluster-initial-membership",NULL), node.sizes=os_seurat_option(a,"cluster-node-sizes",NULL), resolution=a$resolution, method=NULL, algorithm=a$algorithm, leiden_method=os_seurat_option(a,"cluster-leiden-method",c("leidenbase", "igraph")), leiden_objective_function=os_seurat_option(a,"cluster-leiden-objective-function",c("modularity", "CPM")), n.start=os_seurat_option(a,"cluster-n-start",10), n.iter=os_seurat_option(a,"cluster-n-iter",10), random.seed=a$seed, group.singletons=os_seurat_option(a,"cluster-group-singletons",TRUE), temp.file.location=NULL, edge.file.name=NULL, verbose=FALSE, object=x)
